$fn = 180;

bore_d = 5.0;
od_d = 16.0;
width = 5.0;

flange_d = 18.0;
flange_th = 1.0;

chamfer = 0.35;          // small edge chamfer
race_depth = 0.6;        // shallow groove depth
race_width = 1.2;        // groove width

module chamfered_cylinder(d=10, h=5, c=0.3) {
    c = min(c, h/2, d/4);
    union() {
