            translate([0,0,z_can0])
                cylinder(d=can_d, h=can_h + overlap, center=false);

            // Hollow interior (leave wall thickness)
            translate([0,0,z_can0 + can_wall])
                cylinder(d=can_d - 2*can_wall, h=can_h + overlap - 2*can_wall, center=false);

