    pts_inner = [
        for(i=[steps:-1:0])
            let(t=i/steps,
                a=ang0 + (ang1-ang0)*t,
                r=(scroll_r0 + (scroll_r1-scroll_r0)*t) - band)
            [r*cos(a), r*sin(a)]
