// Common HT DN90 assumptions:
// - Outer diameter: 90 mm
// - Wall thickness: 2.7 mm
// - Straight segment length: 250 mm
// - Small chamfers on both ends

od = 90;
wall = 2.7;
id = od - 2*wall;

L = 250;          // pipe length
