                    rotate([90,0,0])
                        linear_extrude(height=w+0.2, center=true)
                            polygon(points=[[0,0],[c,0],[0,c]]);
        }

        // Bottom chamfers
        translate([0,0,-h/2 + c/2]){
            for (sy=[-1,1])
                translate([0, sy*(w/2 - c/2), 0])
                    rotate([0,90,0])
                        linear_extrude(height=l+0.2, center=true)
                            polygon(points=[[0,0],[c,0],[0,c]]);
            for (sx=[-1,1])
                translate([sx*(l/2 - c/2), 0, 0])
                    rotate([90,0,0])
                        linear_extrude(height=w+0.2, center=true)
                            polygon(points=[[0,0],[c,0],[0,c]]);
