        color([0.1, 0.1, 0.1])
        translate([0,  header_y_offset, z_top - eps])
            pin_header_row(n=header_n, pitch=header_pitch, pin=1.0, h=header_pin_h, base_h=header_base_h, base_w=header_base_w);

        color([0.1, 0.1, 0.1])
        translate([0, -header_y_offset, z_top - eps])
            pin_header_row(n=header_n, pitch=header_pitch, pin=1.0, h=header_pin_h, base_h=header_base_h, base_w=header_base_w);

