// -------- Helpers --------
module rounded_block(size=[10,10,10], r=2) {
    sx = max(size[0]-2*r, 0.01);
    sy = max(size[1]-2*r, 0.01);
    sz = max(size[2]-2*r, 0.01);
    minkowski() {
        cube([sx, sy, sz], center=true);
        sphere(r=r);
    }
