module capsule2d_x(d=10, len=20) {
    hull() {
        translate([-len/2,0]) circle(d=d);
        translate([ len/2,0]) circle(d=d);
    }
}

module capsule_x(d=20, len=30, h=1, center=true) {
    linear_extrude(height=h, center=center)
        capsule2d_x(d=d, len=len);
