module slot_through_base(xc=0, yc=0, len=18, w=11, h=20) {
    // Slot is a capsule in XY, extruded in Z
    translate([xc, yc, base_H/2])
        linear_extrude(height=h, center=true)
            capsule2d_x(d=w, len=len);
