module rounded_box(l,w,h,r){
    // robust for small r; keep positive core
    core_l = max(l-2*r, 0.01);
    core_w = max(w-2*r, 0.01);
    core_h = max(h-2*r, 0.01);
    minkowski(){
        cube([core_l, core_w, core_h], center=true);
        sphere(r=r);
