    if (slot <= 0){
        cylinder(d=d, h=h, center=true);
    } else {
        hull(){
            translate([-slot/2,0,0]) cylinder(d=d, h=h, center=true);
            translate([ slot/2,0,0]) cylinder(d=d, h=h, center=true);
        }
    }
