                rotate([0,90,0])
                    cylinder(d=housing_outer_d, h=housing_len, center=true);

            // Blend boss to saddle (ensures robust connection)
            hull(){
                translate([0,0,z_saddle_c])
                    cube([saddle_L*0.92, saddle_W*0.92, 0.2], center=true);
                translate([0,0,z_shaft])
                    rotate([0,90,0])
