        [ w/2 - c2, -l/2],
        [ w/2, -l/2 + c2],
        [ w/2,  l/2 - c2],
        [ w/2 - c2,  l/2],
        [-w/2 + c2,  l/2],
        [-w/2,  l/2 - c2],
