module thread_ridge(len, d_major, p, depth, w) {
    r = d_major/2 - depth/2;
    turns = len / p;
    linear_extrude(height=len, twist=turns*360, slices=max(ceil(turns*24), 24), convexity=10)
        translate([r, 0, 0])
            square([depth, w], center=true);
