module phillips_recess() {
    // Cut from near top down by drive_depth
    translate([0,0,head_h - drive_depth - eps])
    union() {
        linear_extrude(height = drive_depth + 2*eps, scale = 0.85, convexity=10)
            square([drive_len, drive_w], center=true);
