    // The 2D profile is in (radius, z) plane; we revolve it around Z.
    linear_extrude(height=len, twist=360*len/p, slices=max(ceil(len*24/p), 60), convexity=10)
        rotate([0,0,0])
            polygon([
                [rmin, -w/2],
                [rmaj,  0   ],
                [rmin,  w/2]
            ]);
