pin_head_r = 3.2;   // pin head radius (visual)
pin_head_t = 1.2;   // pin head thickness
lever_t = 2.0;      // small cam/lever thickness
lever_w = 7.0;      // lever width (Y)
lever_len = 10.0;   // lever length (X)
