module rounded_box(size=[100,100,50], r=6){
    x=size[0]; y=size[1]; z=size[2];
    r2=min(r, min(x,y)/2-0.01);
    minkowski(){
        cube([x-2*r2, y-2*r2, z-2*r2], center=true);
        sphere(r=r2);
