module vent_band(){
    // slots around the side
    n = 28;
    for(i=[0:n-1]){
        a = i*360/n;
        translate([0,0,18])
        rotate([0,0,a])
        translate([base_d/2-1.2,0,0])
            rotate([0,90,0])
                cube([vent_slot_depth, vent_slot_w, vent_slot_h], center=true);
    }
